-- DevStaging only. All profile changes and generated notifications roll back.
begin;
create temp table profile_test_results(label text,passed boolean);
grant select,insert on profile_test_results to authenticated,anon,service_role;
create function pg_temp.check_test(label text,value boolean) returns void language plpgsql as $$ begin if value is distinct from true then raise exception 'FAILED: %',label; end if; insert into profile_test_results values(label,true); end; $$;
create function pg_temp.deny(label text,statement text,state text default '42501') returns void language plpgsql as $$ declare denied boolean:=false; begin begin execute statement; exception when others then if sqlstate<>state then raise exception 'FAILED: %, expected %, got %',label,state,sqlstate; end if; denied:=true; end; perform pg_temp.check_test(label,denied); end; $$;
create function pg_temp.actor(id uuid) returns void language plpgsql as $$ begin perform set_config('request.jwt.claim.sub',coalesce(id::text,''),true); perform set_config('request.jwt.claims',case when id is null then '{}' else json_build_object('sub',id,'role','authenticated')::text end,true); end; $$;
do $$ declare fixture record; youth_b uuid; company_b uuid; begin
select j.id as job,j.company_user_id as company,y.user_id as youth,y.recruitment_profile_version as version into fixture from public.swipe_actions s join public.jobs j on j.id=s.job_id join public.company_profiles cp on cp.user_id=j.company_user_id join public.youth_profiles y on y.user_id=s.youth_user_id where s.decision='interested' and private.application_analysis_eligible(j.id,y.user_id) and cp.verification_status='verified' and not public.users_are_blocked(cp.user_id,y.user_id) limit 1;
if fixture.job is null then raise exception 'Missing DEV fixture'; end if;
select user_id into youth_b from public.youth_profiles where user_id<>fixture.youth limit 1;
select user_id into company_b from public.company_profiles where user_id<>fixture.company and verification_status='verified' limit 1;
if youth_b is null or company_b is null then raise exception 'Missing DEV isolation actors'; end if;
perform set_config('mnw.profile_fixture',jsonb_build_object('job',fixture.job,'company',fixture.company,'youth',fixture.youth,'version',fixture.version,'youth_b',youth_b,'company_b',company_b)::text,true);
end; $$;
create function pg_temp.fixture(key text) returns text language sql as $$ select current_setting('mnw.profile_fixture')::jsonb->>key; $$;
delete from public.application_analysis_jobs where job_id=pg_temp.fixture('job')::uuid and youth_user_id=pg_temp.fixture('youth')::uuid;
set local role anon;
select pg_temp.actor(null);
select pg_temp.deny('anonymous cannot claim jobs','select public.claim_application_analysis_jobs()');
select pg_temp.deny('anonymous cannot read queue','select * from public.application_analysis_jobs');
set local role authenticated;
select pg_temp.actor(pg_temp.fixture('company')::uuid);
select pg_temp.deny('company cannot claim worker jobs','select public.claim_application_analysis_jobs()');
select pg_temp.deny('company cannot read queue directly','select * from public.application_analysis_jobs');
select public.request_application_assessment(pg_temp.fixture('job')::uuid,pg_temp.fixture('youth')::uuid);
select public.request_application_assessment(pg_temp.fixture('job')::uuid,pg_temp.fixture('youth')::uuid);
select pg_temp.check_test('authorized owner sees pending',public.get_application_assessment_state(pg_temp.fixture('job')::uuid,pg_temp.fixture('youth')::uuid)->>'status'='pending');
select pg_temp.actor(pg_temp.fixture('company_b')::uuid);
select pg_temp.deny('unrelated company cannot enqueue','select public.request_application_assessment('||quote_literal(pg_temp.fixture('job'))||'::uuid,'||quote_literal(pg_temp.fixture('youth'))||'::uuid)');
select pg_temp.deny('unrelated company cannot read assessment state','select public.get_application_assessment_state('||quote_literal(pg_temp.fixture('job'))||'::uuid,'||quote_literal(pg_temp.fixture('youth'))||'::uuid)');
reset role;
select pg_temp.check_test('repeat requests coalesce',(select count(*)=1 from public.application_analysis_jobs where job_id=pg_temp.fixture('job')::uuid and youth_user_id=pg_temp.fixture('youth')::uuid));
update public.application_analysis_jobs set available_at='2000-01-01' where job_id=pg_temp.fixture('job')::uuid and youth_user_id=pg_temp.fixture('youth')::uuid;
create function pg_temp.queue_token() returns uuid language sql as $$ select lock_token from public.application_analysis_jobs where job_id=pg_temp.fixture('job')::uuid and youth_user_id=pg_temp.fixture('youth')::uuid; $$;
create function pg_temp.queue_generation() returns bigint language sql as $$ select generation from public.application_analysis_jobs where job_id=pg_temp.fixture('job')::uuid and youth_user_id=pg_temp.fixture('youth')::uuid; $$;
set local role service_role;
select pg_temp.check_test('invalid cron token denied',public.validate_matching_worker_token(repeat('0',64))=false);
select pg_temp.check_test('worker claims fixture',exists(select 1 from jsonb_array_elements(public.claim_application_analysis_jobs()) task where task->>'jobId'=pg_temp.fixture('job')));
select set_config('mnw.queue_old_token',pg_temp.queue_token()::text,true),set_config('mnw.queue_old_generation',pg_temp.queue_generation()::text,true);
select pg_temp.check_test('second worker cannot claim active lease',not exists(select 1 from jsonb_array_elements(public.claim_application_analysis_jobs()) task where task->>'jobId'=pg_temp.fixture('job')));
reset role;
update public.youth_profiles set recruitment_profile=jsonb_set(recruitment_profile,'{preferences,motivation}',to_jsonb('Synthetic queue change'::text)) where user_id=pg_temp.fixture('youth')::uuid;
set local role service_role;
select pg_temp.check_test('source update increments generation',pg_temp.queue_generation()>current_setting('mnw.queue_old_generation')::bigint);
select pg_temp.check_test('old result rejected',public.finish_application_analysis_job(pg_temp.fixture('job')::uuid,pg_temp.fixture('youth')::uuid,current_setting('mnw.queue_old_generation')::bigint,current_setting('mnw.queue_old_token')::uuid,repeat('a',64),'{"criteria":[]}','[]','[]')->>'stale'='true');
select pg_temp.check_test('stale result requeues',(select status='pending' from public.application_analysis_jobs where job_id=pg_temp.fixture('job')::uuid and youth_user_id=pg_temp.fixture('youth')::uuid));
update public.application_analysis_jobs set available_at='2000-01-01' where job_id=pg_temp.fixture('job')::uuid and youth_user_id=pg_temp.fixture('youth')::uuid;
select pg_temp.check_test('new generation claimed',exists(select 1 from jsonb_array_elements(public.claim_application_analysis_jobs()) task where task->>'jobId'=pg_temp.fixture('job')));
select pg_temp.check_test('worker persists assessment',public.finish_application_analysis_job(pg_temp.fixture('job')::uuid,pg_temp.fixture('youth')::uuid,pg_temp.queue_generation(),pg_temp.queue_token(),repeat('b',64),'{"criteria":[],"source":"rules"}','[]','[]')->>'completed'='true');
select pg_temp.check_test('duplicate completion ignored',public.finish_application_analysis_job(pg_temp.fixture('job')::uuid,pg_temp.fixture('youth')::uuid,pg_temp.queue_generation(),current_setting('mnw.queue_old_token')::uuid,repeat('b',64),'{"criteria":[]}','[]','[]')->>'stale'='true');
set local role authenticated;
select pg_temp.actor(pg_temp.fixture('company')::uuid);
select pg_temp.check_test('owner sees automatic stored assessment',public.get_application_assessment_state(pg_temp.fixture('job')::uuid,pg_temp.fixture('youth')::uuid)->'assessment'->>'source'='rules');
reset role;
update public.application_analysis_jobs set status='pending',attempts=0,available_at='2000-01-01' where job_id=pg_temp.fixture('job')::uuid and youth_user_id=pg_temp.fixture('youth')::uuid;
set local role service_role;
select pg_temp.check_test('retry test claims job',exists(select 1 from jsonb_array_elements(public.claim_application_analysis_jobs()) task where task->>'jobId'=pg_temp.fixture('job')));
select public.fail_application_analysis_job(pg_temp.fixture('job')::uuid,pg_temp.fixture('youth')::uuid,pg_temp.queue_generation(),pg_temp.queue_token());
select pg_temp.check_test('provider failure retains job and delays retry',(select status='failed' and available_at>now() and lock_token is null from public.application_analysis_jobs where job_id=pg_temp.fixture('job')::uuid and youth_user_id=pg_temp.fixture('youth')::uuid));
reset role;
update public.application_analysis_jobs set status='pending',attempts=0,available_at='2000-01-01' where job_id=pg_temp.fixture('job')::uuid and youth_user_id=pg_temp.fixture('youth')::uuid;
insert into public.user_blocks(blocker_user_id,blocked_user_id) values(pg_temp.fixture('youth')::uuid,pg_temp.fixture('company')::uuid) on conflict do nothing;
set local role service_role;
select pg_temp.check_test('blocked application is not processed',not exists(select 1 from jsonb_array_elements(public.claim_application_analysis_jobs()) task where task->>'jobId'=pg_temp.fixture('job')));
select pg_temp.check_test('blocked task cancelled',(select status='cancelled' from public.application_analysis_jobs where job_id=pg_temp.fixture('job')::uuid and youth_user_id=pg_temp.fixture('youth')::uuid));
reset role;
select jsonb_build_object('passed',count(*),'tests',jsonb_agg(label)) from profile_test_results;
rollback;
